import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def load_xyz(path):
    with open(path) as f:
        lines = f.read().splitlines()
    n = int(lines[0]); syms=[]; coords=[]
    for ln in lines[2:2+n]:
        p = ln.split()
        syms.append(p[0]); coords.append([float(p[1]),float(p[2]),float(p[3])])
    return syms, np.array(coords)

syms, c = load_xyz('answer.xyz')
colors = {'C':'#666666','H':'#dddddd','N':'#3050f8','O':'#ff0d0d','P':'#ff8000','Pd':'#006985'}
sizes = {'C':180,'H':40,'N':300,'O':300,'P':450,'Pd':700}

def bonds_for(syms, c):
    bonds=[]
    for i in range(len(c)):
        for j in range(i+1,len(c)):
            d = np.linalg.norm(c[i]-c[j])
            if syms[i]=='Pd' or syms[j]=='Pd':
                if d < 2.6: bonds.append((i,j))
            elif d < 1.75: bonds.append((i,j))
    return bonds
bonds = bonds_for(syms, c)

def render(elev, azim, fname):
    fig = plt.figure(figsize=(10,10))
    ax = fig.add_subplot(111, projection='3d')
    for (i,j) in bonds:
        ax.plot([c[i,0],c[j,0]],[c[i,1],c[j,1]],[c[i,2],c[j,2]], color='#999999', lw=1.5)
    for i,s in enumerate(syms):
        ax.scatter(c[i,0],c[i,1],c[i,2], s=sizes[s], color=colors[s], edgecolors='black', linewidths=0.4, depthshade=False)
    ax.set_box_aspect((np.ptp(c[:,0]), np.ptp(c[:,1]), np.ptp(c[:,2])))
    ax.view_init(elev=elev, azim=azim)
    ax.set_axis_off()
    plt.tight_layout()
    plt.savefig(fname, dpi=130, facecolor='white')
    plt.close()

render(80, -90, 'render2.png')   # top-down
render(5, 20, 'render3.png')     # side
print("saved")
